\label{thm:fol_1D_basic}
Let Assumptions \ref{A:A1} and \ref{A:z} hold. Then for every $\theta\in [0,2\pi)$,
\begin{enumerate}[(i)]
	\item $\Phi^t$ maps the fibre $\mathcal{F}_\theta$ homeomorphically onto the fibre $\mathcal{F}_{\theta+\omega t \bmod 2\pi}$. 
	\item The images $\Phi^{2\pi t/\omega}(\mathcal{F}_\theta)$ are disjoint, for $0\leq t<1$, and their union is the whole set $X$.
	\item $\Phi^t_{*}\left(\mu|\mathcal{F}_{\theta}\right)$ = $\mu|\mathcal{F}_{\theta+\omega t \bmod 2\pi}$.
	\item The following map $\Psi$ is a continuous bijection.

	\begin{equation}\label{eqn:def:Iso1}	
	\Psi : \calL_1 \times [0,1)\to X; \quad \Psi(y,t) := \Phi^{t \cdot 2\pi/\omega} y
	\end{equation}

	Moreover $\Psi$ transforms the product measure $\left(\mu | \calL_1\right)\times \Leb$ into the invariant measure $\mu$. 
	\item If $z$ was an $L^2(\mu)$ eigenfunction instead, then these claims are true upto a set of $\mu$-measure $0$.
\end{enumerate}

\begin{equation}\label{eqn:def:Iso1}	
	\Psi : \calL_1 \times [0,1)\to X; \quad \Psi(y,t) := \Phi^{t \cdot 2\pi/\omega} y
	\end{equation}

Then the suspension flow \emph{with base $\calL_1$, return map $R$ and height $1$} is a flow $\Gamma^t$ on $\calL_1 \times \real / \sim$, defined as 

\begin{equation}\label{eqn:def:susp_flow}
\Gamma^t(x,s) := \left( R^N(x), s+t-N \right), \quad \mbox{ where } N\in\integer \mbox{ is such that } 0\leq s+t-N<1.
\end{equation}

\begin{equation}\label{eqn:def:susp_flow}
